import React, { useState, useEffect } from 'react';

function App() {
  // Les states mta3 l'API Hello
  const [helloMessage, setHelloMessage] = useState("");
  const [loadingHello, setLoadingHello] = useState(true);

  // Les states mta3 l'API Tasks (Base de données)
  const [tasks, setTasks] = useState([]);
  const [loadingTasks, setLoadingTasks] = useState(true);

  useEffect(() => {
    const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:8080';

    // 1. Njibou l'message Hello
    fetch(`${apiUrl}/api/hello`)
      .then(response => response.json())
      .then(data => {
        setHelloMessage(data.message);
        setLoadingHello(false);
      })
      .catch(error => {
        console.error("Erreur API Hello:", error);
        setHelloMessage("Erreur de connexion m3a l'API Spring Boot!");
        setLoadingHello(false);
      });

    // 2. Njibou l'liste des Tâches
    fetch(`${apiUrl}/api/tasks`)
      .then(response => response.json())
      .then(data => {
        setTasks(data);
        setLoadingTasks(false);
      })
      .catch(error => {
        console.error("Erreur API Tasks:", error);
        setLoadingTasks(false);
      });
  }, []);

  return (
    <div style={{ textAlign: 'center', marginTop: '50px', fontFamily: 'Arial' }}>
      <h1>Application 3 Tiers (React + Spring Boot + MariaDB)</h1>

      {/* Boîte 1: L'API Hello */}
      <div style={{ margin: '20px auto', padding: '20px', border: '2px solid #ccc', borderRadius: '10px', width: '50%' }}>
        <h3>Message mil Backend (Test API) :</h3>
        {loadingHello ? (
          <p>Y'chargi fi l'message...</p>
        ) : (
          <p style={{ color: 'green', fontWeight: 'bold', fontSize: '18px' }}>{helloMessage}</p>
        )}
      </div>

      {/* Boîte 2: L'API Tasks */}
      <div style={{ margin: '20px auto', padding: '20px', border: '2px solid #007bff', borderRadius: '10px', width: '50%' }}>
        <h3>Liste des Tâches (Depuis MariaDB) :</h3>
        {loadingTasks ? (
          <p>Y'chargi fi l'data...</p>
        ) : (
          <ul style={{ listStyleType: 'none', padding: 0 }}>
            {tasks.map(task => (
              <li key={task.id} style={{ margin: '10px auto', padding: '15px', border: '1px solid #ccc', borderRadius: '5px', backgroundColor: '#f9f9f9' }}>
                <strong>{task.id}</strong> - {task.title}
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

export default App;
